def find_edges(n, degrees_and_xors):
    edges = []
    vertices = [[] for _ in range(n)]
    degree_sum = 0

    for i in range(n):
        degree, xor_sum = degrees_and_xors[i]
        degree_sum += degree
        if degree == 0:
            continue
        for j in range(n):
            if (i, j) not in edges and (j, i) not in edges:
                new_degree = degree - 1
                new_xor_sum = xor_sum ^ j
                if new_degree == 0:
                    edges.append((i, j))
                    vertices[i].append(j)
                    vertices[j].append(i)
                    break
                elif new_degree > 0 and new_xor_sum < 2**16:
                    edges.append((i, j))
                    vertices[i].append(j)
                    vertices[j].append(i) 
                    break

    return edges

def main():
    n = int(input())
    degrees_and_xors = [tuple(map(int, input().split())) for _ in range(n)]

    edges = find_edges(n, degrees_and_xors)

    print(len(edges))
    for edge in edges:
        print(*edge)

if __name__ == "__main__":
    main()
